"use client"

import * as React from "react"
import {
  ChevronDown,
  ChevronRight,
  ChevronsUpDown,
  PanelLeftIcon,
  Search,
} from "lucide-react"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
  Sidebar,
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

export type RailDot =
  | "chart-1"
  | "chart-2"
  | "chart-3"
  | "chart-4"
  | "chart-5"
  | "primary"
  | "muted"
  | "destructive"

export type RailLinkRenderProps = {
  href: string
  className?: string
  children: React.ReactNode
  "aria-current"?: "page"
  onClick?: (event: React.MouseEvent<HTMLElement>) => void
}

export type RailLink = {
  id: string
  label: string
  href?: string
  icon?: React.ReactNode
  badge?: string | number
  /** Alert counts use the destructive tone. */
  badgeTone?: "default" | "alert"
  dot?: RailDot
  disabled?: boolean
  /** Single element, such as a Next.js or React Router link. */
  asChild?: React.ReactElement
}

export type RailEntry = RailLink & {
  /** When set, the entry is a collapsible group of sub-items. */
  items?: readonly RailLink[]
  defaultOpen?: boolean
}

export type RailScope = {
  label: string
  options: readonly { value: string; label: string }[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
}

export type RailFooterLink = {
  id: string
  label: string
  href?: string
  count?: number
  onSelect?: () => void
}

export type RailNavGroup = {
  id: string
  /** Omit for a flat list with no heading. */
  label?: string
  items: readonly RailEntry[]
}

export type RailSection = {
  id: string
  label: string
  icon: React.ReactNode
  badge?: string | number
  /** Secondary sections sit above the avatar. */
  placement?: "primary" | "secondary"
  nav: readonly RailNavGroup[]
  /** Extra control beside the section title, such as add or a menu. */
  action?: React.ReactNode
  /** Optional leading row, for example every open record and its count. */
  all?: { label: string; href?: string; count?: number }
}

export type RailWorkspaceOption = {
  id: string
  name: string
  subtitle?: string
  logo?: React.ReactNode
}

export type RailWorkspace = {
  name: string
  subtitle?: string
  logo?: React.ReactNode
  options?: readonly RailWorkspaceOption[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  status?: "online" | "away" | "offline"
}

export type RailUser = {
  name: string
  email?: string
  avatarUrl?: string
}

export type RailSidebarProps = {
  sections: readonly RailSection[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
  /** Href of the current page. Matching links get aria-current="page". */
  activeHref?: string
  renderLink?: (props: RailLinkRenderProps) => React.ReactElement
  onNavigate?: (href: string) => void
  workspace?: RailWorkspace
  user?: RailUser
  /** Menu body for the user dropdown. Render menu items here. */
  footerSlot?: React.ReactNode
  onSearch?: (query: string) => void
  onOpenCommand?: () => void
  searchPlaceholder?: string
  /** One collapsible entry open at a time, or several. */
  type?: "single" | "multiple"
  /** Passed to the shadcn sidebar. "icon" keeps the rail and hides the panel. */
  collapsible?: "offcanvas" | "icon" | "none"
  /** In-flow layout for thumbnails, tests, and narrow containers. */
  contained?: boolean
  mark?: React.ReactNode
  markLabel?: string
  children?: React.ReactNode
  className?: string
  railClassName?: string
  panelClassName?: string
  itemClassName?: string
  groupClassName?: string
  headerClassName?: string
  footerClassName?: string
  searchClassName?: string
  insetClassName?: string
  railLabel?: string
  panelLabel?: string
  searchLabel?: string
  commandLabel?: string
  collapseLabel?: string
  expandLabel?: string
  scope?: RailScope
  footerLinks?: readonly RailFooterLink[]
}

const DOT_CLASS: Record<RailDot, string> = {
  "chart-1": "bg-chart-1",
  "chart-2": "bg-chart-2",
  "chart-3": "bg-chart-3",
  "chart-4": "bg-chart-4",
  "chart-5": "bg-chart-5",
  primary: "bg-primary",
  muted: "bg-muted-foreground",
  destructive: "bg-destructive",
}

function useControllable(value: string | undefined, defaultValue: string | undefined, onChange?: (next: string) => void) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue ?? "")
  const selected = value ?? uncontrolled
  const setSelected = React.useCallback(
    (next: string) => {
      if (value === undefined) setUncontrolled(next)
      onChange?.(next)
    },
    [onChange, value],
  )
  return [selected, setSelected] as const
}

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

function ItemBody({ item, className }: { item: RailLink; className?: string }) {
  return (
    <>
      {item.dot ? (
        <span className={cn("size-2 shrink-0 rounded-full", DOT_CLASS[item.dot])} aria-hidden />
      ) : item.icon ? (
        <span className="text-muted-foreground [&_svg]:size-4" aria-hidden>
          {item.icon}
        </span>
      ) : null}
      <span className={cn("min-w-0 flex-1 truncate text-start", className)}>{item.label}</span>
      {item.badge != null && item.badge !== "" ? (
        <Badge
          variant="secondary"
          className={cn("ms-auto tabular-nums", item.badgeTone === "alert" && "bg-destructive/10 text-destructive")}
        >
          {item.badge}
        </Badge>
      ) : null}
    </>
  )
}

function RailAnchor({
  item,
  active,
  className,
  renderLink,
  onNavigate,
}: {
  item: RailLink
  active: boolean
  className: string
  renderLink?: RailSidebarProps["renderLink"]
  onNavigate?: (href: string) => void
}) {
  const current = active ? "page" : undefined
  const onClick = (event: React.MouseEvent<HTMLElement>) => {
    if (item.disabled) {
      event.preventDefault()
      return
    }
    if (item.href && onNavigate) {
      event.preventDefault()
      onNavigate(item.href)
    }
  }

  if (item.asChild) {
    return (
      <Slot.Root
        className={className}
        aria-current={current}
        aria-disabled={item.disabled || undefined}
        onClick={onClick}
      >
        {React.cloneElement(item.asChild, undefined, <ItemBody item={item} />)}
      </Slot.Root>
    )
  }

  if (item.href && renderLink) {
    return renderLink({
      href: item.href,
      className,
      "aria-current": current,
      onClick,
      children: <ItemBody item={item} />,
    })
  }

  if (item.href) {
    return (
      <a
        href={item.href}
        className={className}
        aria-current={current}
        aria-disabled={item.disabled || undefined}
        onClick={onClick}
      >
        <ItemBody item={item} />
      </a>
    )
  }

  return (
    <button type="button" className={className} disabled={item.disabled} aria-current={current} onClick={onClick}>
      <ItemBody item={item} />
    </button>
  )
}

function entryOpen(type: "single" | "multiple", single: string | null, many: readonly string[], id: string) {
  return type === "single" ? single === id : many.includes(id)
}

function RailColumns({
  sections,
  sectionId,
  onSectionChange,
  activeHref,
  renderLink,
  onNavigate,
  workspace,
  user,
  footerSlot,
  onSearch,
  onOpenCommand,
  searchPlaceholder,
  type,
  panelVisible,
  onTogglePanel,
  mark,
  markLabel,
  className,
  railClassName,
  panelClassName,
  itemClassName,
  groupClassName,
  headerClassName,
  footerClassName,
  searchClassName,
  railLabel,
  panelLabel,
  searchLabel,
  commandLabel,
  collapseLabel,
  expandLabel,
  showCollapse,
  scope,
  footerLinks,
}: {
  sections: readonly RailSection[]
  sectionId: string
  onSectionChange: (id: string) => void
  panelVisible: boolean
  onTogglePanel?: () => void
  showCollapse: boolean
} & Pick<
  RailSidebarProps,
  | "activeHref"
  | "renderLink"
  | "onNavigate"
  | "workspace"
  | "user"
  | "footerSlot"
  | "onSearch"
  | "onOpenCommand"
  | "searchPlaceholder"
  | "type"
  | "mark"
  | "markLabel"
  | "className"
  | "railClassName"
  | "panelClassName"
  | "itemClassName"
  | "groupClassName"
  | "headerClassName"
  | "footerClassName"
  | "searchClassName"
  | "railLabel"
  | "panelLabel"
  | "searchLabel"
  | "commandLabel"
  | "collapseLabel"
  | "expandLabel"
  | "scope"
  | "footerLinks"
>) {
  const accordion = type ?? "single"
  const railRef = React.useRef<HTMLElement>(null)
  const section = sections.find((item) => item.id === sectionId) ?? sections[0]
  const primary = sections.filter((item) => item.placement !== "secondary")
  const secondary = sections.filter((item) => item.placement === "secondary")
  const [workspaceId, setWorkspaceId] = useControllable(
    workspace?.value,
    workspace?.defaultValue ?? workspace?.options?.[0]?.id,
    workspace?.onValueChange,
  )
  const activeWorkspace =
    workspace?.options?.find((option) => option.id === workspaceId) ??
    (workspace
      ? { id: workspaceId, name: workspace.name, subtitle: workspace.subtitle, logo: workspace.logo }
      : undefined)

  const sectionKey = section?.id ?? ""
  const defaultOpenIds = section?.nav.flatMap((group) =>
    group.items.filter((item) => item.defaultOpen && item.items?.length).map((item) => item.id),
  ) ?? []
  const [openBySection, setOpenBySection] = React.useState<Record<string, { single: string | null; many: string[] }>>({})
  const openState = openBySection[sectionKey] ?? {
    single: defaultOpenIds[0] ?? null,
    many: defaultOpenIds,
  }
  const singleOpen = openState.single
  const manyOpen = openState.many

  React.useEffect(() => {
    if (!onOpenCommand) return
    const onKey = (event: KeyboardEvent) => {
      if (event.key.toLowerCase() !== "k" || !(event.metaKey || event.ctrlKey)) return
      event.preventDefault()
      onOpenCommand()
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [onOpenCommand])

  function toggleEntry(id: string) {
    setOpenBySection((current) => {
      const previous = current[sectionKey] ?? {
        single: defaultOpenIds[0] ?? null,
        many: defaultOpenIds,
      }
      if (accordion === "single") {
        return { ...current, [sectionKey]: { ...previous, single: previous.single === id ? null : id } }
      }
      const many = previous.many.includes(id) ? previous.many.filter((item) => item !== id) : [...previous.many, id]
      return { ...current, [sectionKey]: { ...previous, many } }
    })
  }

  function onRailKeyDown(event: React.KeyboardEvent<HTMLElement>) {
    const keys = ["ArrowDown", "ArrowUp", "Home", "End"]
    if (!keys.includes(event.key)) return
    const buttons = [...(railRef.current?.querySelectorAll<HTMLButtonElement>("[data-rail-section]") ?? [])]
    if (!buttons.length) return
    event.preventDefault()
    const index = buttons.findIndex((button) => button === document.activeElement)
    const next =
      event.key === "Home"
        ? 0
        : event.key === "End"
          ? buttons.length - 1
          : event.key === "ArrowDown"
            ? (Math.max(index, 0) + 1) % buttons.length
            : (index <= 0 ? buttons.length : index) - 1
    buttons[next]?.focus()
  }

  const itemClass = cn(
    "flex w-full min-w-0 items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:bg-card aria-[current=page]:font-medium aria-[current=page]:shadow-sm",
    itemClassName,
  )

  const userMenu = user ? (
    <DropdownMenuContent align="start" className="w-56">
      <DropdownMenuLabel className="font-normal">
        <span className="block truncate text-sm font-medium">{user.name}</span>
        {user.email ? <span className="block truncate text-xs text-muted-foreground">{user.email}</span> : null}
      </DropdownMenuLabel>
      {footerSlot}
    </DropdownMenuContent>
  ) : null

  return (
    <TooltipProvider>
      <div className={cn("flex h-full min-h-0 w-full min-w-0", className)}>
        <nav
          ref={railRef}
          aria-label={railLabel ?? "Sections"}
          onKeyDown={onRailKeyDown}
          className={cn(
            "flex w-12 shrink-0 flex-col items-center gap-1 border-e border-border bg-sidebar px-1.5 py-2 text-sidebar-foreground",
            railClassName,
          )}
        >
          <div className="relative mb-1">
            <div className="grid size-8 place-items-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">
              {mark ?? (markLabel ?? workspace?.name ?? "A").slice(0, 1)}
            </div>
            {workspace?.status ? <StatusDot status={workspace.status} /> : null}
          </div>
          <div className="flex w-full flex-col items-center gap-1">
            {primary.map((item) => (
              <RailSectionButton
                key={item.id}
                item={item}
                pressed={item.id === section?.id}
                onSelect={onSectionChange}
              />
            ))}
          </div>
          <div className="mt-auto flex w-full flex-col items-center gap-1">
            {showCollapse && onTogglePanel ? (
              <button
                type="button"
                onClick={onTogglePanel}
                aria-pressed={panelVisible}
                aria-label={panelVisible ? (collapseLabel ?? "Collapse panel") : (expandLabel ?? "Expand panel")}
                className="grid size-8 place-items-center rounded-md text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <PanelLeftIcon className="size-4" />
              </button>
            ) : null}
            {secondary.map((item) => (
              <RailSectionButton
                key={item.id}
                item={item}
                pressed={item.id === section?.id}
                onSelect={onSectionChange}
              />
            ))}
            {user ? (
              panelVisible ? (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="mt-1 inline-flex">
                      <Avatar size="sm">
                        {user.avatarUrl ? <AvatarImage src={user.avatarUrl} alt="" /> : null}
                        <AvatarFallback>{initials(user.name)}</AvatarFallback>
                      </Avatar>
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>{user.name}</TooltipContent>
                </Tooltip>
              ) : (
                <DropdownMenu>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <DropdownMenuTrigger
                        aria-label={user.name}
                        className="mt-1 rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                      >
                        <Avatar size="sm">
                          {user.avatarUrl ? <AvatarImage src={user.avatarUrl} alt="" /> : null}
                          <AvatarFallback>{initials(user.name)}</AvatarFallback>
                        </Avatar>
                      </DropdownMenuTrigger>
                    </TooltipTrigger>
                    <TooltipContent>{user.name}</TooltipContent>
                  </Tooltip>
                  {userMenu}
                </DropdownMenu>
              )
            ) : null}
          </div>
        </nav>

        {panelVisible ? (
          <div
            id="rail-panel"
            role="region"
            aria-label={panelLabel ?? section?.label ?? "Navigation"}
            className={cn("flex min-w-0 flex-1 flex-col bg-card", panelClassName)}
          >
            <div className={cn("flex flex-col gap-2 p-3", headerClassName)}>
              {workspace && activeWorkspace ? (
                workspace.options && workspace.options.length > 0 ? (
                  <DropdownMenu>
                    <DropdownMenuTrigger
                      className="flex w-full items-center gap-2 rounded-lg bg-muted px-2 py-2 text-start hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      <WorkspaceMark logo={activeWorkspace.logo} name={activeWorkspace.name} status={workspace.status} />
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-medium">{activeWorkspace.name}</span>
                        {activeWorkspace.subtitle ? (
                          <span className="block truncate text-xs text-muted-foreground">{activeWorkspace.subtitle}</span>
                        ) : null}
                      </span>
                      <ChevronsUpDown className="size-4 shrink-0 text-muted-foreground" />
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="w-64">
                      {workspace.options.map((option) => (
                        <DropdownMenuItem key={option.id} onSelect={() => setWorkspaceId(option.id)} className="gap-2">
                          <WorkspaceMark logo={option.logo} name={option.name} />
                          <span className="min-w-0">
                            <span className="block truncate">{option.name}</span>
                            {option.subtitle ? (
                              <span className="block truncate text-xs text-muted-foreground">{option.subtitle}</span>
                            ) : null}
                          </span>
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                ) : (
                  <div className="relative flex items-center gap-2 rounded-lg bg-muted px-2 py-2">
                    <WorkspaceMark logo={workspace.logo} name={workspace.name} status={workspace.status} />
                    <span className="min-w-0">
                      <span className="block truncate text-sm font-medium">{workspace.name}</span>
                      {workspace.subtitle ? (
                        <span className="block truncate text-xs text-muted-foreground">{workspace.subtitle}</span>
                      ) : null}
                    </span>
                  </div>
                )
              ) : null}

              <div className="flex items-center justify-between gap-2 px-1">
                <h2 className="min-w-0 truncate text-sm font-medium">{section?.label}</h2>
                {section?.action}
              </div>
              {scope ? <ScopeToggle scope={scope} /> : null}

              <div className={cn("relative", searchClassName)}>
                <Search className="pointer-events-none absolute start-2.5 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  type="search"
                  aria-label={searchLabel ?? "Search"}
                  aria-keyshortcuts="Meta+K"
                  placeholder={searchPlaceholder ?? "Search or ask AI…"}
                  onChange={(event) => onSearch?.(event.target.value)}
                  className="ps-8 pe-14 [&::-webkit-search-cancel-button]:hidden [&::-webkit-search-decoration]:hidden"
                />
                {onOpenCommand ? (
                  <button
                    type="button"
                    onClick={onOpenCommand}
                    aria-label={commandLabel ?? "Open command menu"}
                    className="absolute end-1.5 top-1/2 -translate-y-1/2 rounded-md border border-border bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                  >
                    <kbd>⌘K</kbd>
                  </button>
                ) : (
                  <kbd className="pointer-events-none absolute end-2 top-1/2 -translate-y-1/2 rounded-md border border-border bg-muted px-1.5 py-0.5 text-[10px] text-muted-foreground">
                    ⌘K
                  </kbd>
                )}
              </div>
            </div>

            <div className="min-h-0 flex-1 overflow-y-auto px-2 pb-2">
              {section?.all ? (
                <RailAnchor
                  item={{ id: `${section.id}-all`, label: section.all.label, href: section.all.href ?? "#", badge: section.all.count }}
                  active={Boolean(section.all.href && section.all.href === activeHref)}
                  className={cn(itemClass, "mb-1")}
                  renderLink={renderLink}
                  onNavigate={onNavigate}
                />
              ) : null}
              {section?.nav.map((group) => (
                <div key={group.id} className={cn("mb-2", groupClassName)}>
                  {group.label ? (
                    <p className="truncate px-2 py-1.5 text-xs font-medium text-muted-foreground">{group.label}</p>
                  ) : null}
                  <ul className="flex flex-col gap-0.5">
                    {group.items.map((item) => {
                      const nested = item.items ?? []
                      const open = nested.length > 0 && entryOpen(accordion, singleOpen, manyOpen, item.id)
                      const active = Boolean(item.href && item.href === activeHref)
                      return (
                        <li key={item.id}>
                          {nested.length > 0 ? (
                            <button
                              type="button"
                              aria-expanded={open}
                              aria-controls={`${item.id}-items`}
                              onClick={() => toggleEntry(item.id)}
                              className={itemClass}
                            >
                              {open ? (
                                <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
                              ) : (
                                <ChevronRight className="size-4 shrink-0 text-muted-foreground rtl:rotate-180" />
                              )}
                              <ItemBody item={item} />
                            </button>
                          ) : (
                            <RailAnchor
                              item={item}
                              active={active}
                              className={itemClass}
                              renderLink={renderLink}
                              onNavigate={onNavigate}
                            />
                          )}
                          {nested.length > 0 ? (
                            <div
                              id={`${item.id}-items`}
                              className={cn(
                                "grid transition-[grid-template-rows,opacity] duration-200 ease-out motion-reduce:transition-none",
                                open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
                              )}
                              inert={open ? undefined : true}
                            >
                              <div className="overflow-hidden">
                                <ul className="relative ms-4 flex flex-col gap-0.5 border-s border-border py-0.5 ps-2">
                                  {nested.map((child) => (
                                    <li key={child.id} className="relative before:absolute before:-start-2 before:top-1/2 before:h-px before:w-2 before:bg-border">
                                      <RailAnchor
                                        item={child}
                                        active={Boolean(child.href && child.href === activeHref)}
                                        className={itemClass}
                                        renderLink={renderLink}
                                        onNavigate={onNavigate}
                                      />
                                    </li>
                                  ))}
                                </ul>
                              </div>
                            </div>
                          ) : null}
                        </li>
                      )
                    })}
                  </ul>
                </div>
              ))}
              {!section?.nav.length ? (
                <p className="px-2 py-3 text-sm text-muted-foreground">No links</p>
              ) : null}
            </div>

            {footerLinks?.length ? (
              <ul className="border-t border-border px-2 py-2">
                {footerLinks.map((link) => (
                  <li key={link.id}>
                    <RailAnchor
                      item={{ id: link.id, label: link.label, href: link.href ?? "#", badge: link.count }}
                      active={Boolean(link.href && link.href === activeHref)}
                      className={itemClass}
                      renderLink={renderLink}
                      onNavigate={(href) => {
                        link.onSelect?.()
                        onNavigate?.(href)
                      }}
                    />
                  </li>
                ))}
              </ul>
            ) : null}
            {user ? (
              <div className={cn("border-t border-border p-2", footerClassName)}>
                <DropdownMenu>
                  <DropdownMenuTrigger className="flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-start hover:bg-accent focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">
                    <Avatar size="sm">
                      {user.avatarUrl ? <AvatarImage src={user.avatarUrl} alt="" /> : null}
                      <AvatarFallback>{initials(user.name)}</AvatarFallback>
                    </Avatar>
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-sm font-medium">{user.name}</span>
                      {user.email ? <span className="block truncate text-xs text-muted-foreground">{user.email}</span> : null}
                    </span>
                    <ChevronsUpDown className="size-4 shrink-0 text-muted-foreground" />
                  </DropdownMenuTrigger>
                  {userMenu}
                </DropdownMenu>
              </div>
            ) : footerSlot ? (
              <div className={cn("border-t border-border p-2", footerClassName)}>{footerSlot}</div>
            ) : null}
          </div>
        ) : null}
      </div>
    </TooltipProvider>
  )
}

function WorkspaceMark({ logo, name, status }: { logo?: React.ReactNode; name: string; status?: RailWorkspace["status"] }) {
  return (
    <span className="relative grid size-8 shrink-0 place-items-center rounded-full bg-background text-xs font-semibold">
      {logo ?? initials(name).slice(0, 1)}
      {status ? <StatusDot status={status} /> : null}
    </span>
  )
}

function StatusDot({ status }: { status: NonNullable<RailWorkspace["status"]> }) {
  return (
    <span
      data-status={status}
      className={cn(
        "absolute end-0 bottom-0 size-2 rounded-full ring-2 ring-background",
        status === "online" && "bg-chart-2",
        status === "away" && "bg-chart-4",
        status === "offline" && "bg-muted-foreground",
      )}
      aria-hidden
    />
  )
}

function ScopeToggle({ scope }: { scope: RailScope }) {
  const [internal, setInternal] = React.useState(scope.defaultValue ?? scope.options[0]?.value ?? "")
  const selected = scope.value ?? internal
  function choose(value: string) {
    if (scope.value === undefined) setInternal(value)
    scope.onValueChange?.(value)
  }
  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (!["ArrowRight", "ArrowLeft", "ArrowDown", "ArrowUp"].includes(event.key)) return
    event.preventDefault()
    const index = Math.max(0, scope.options.findIndex((option) => option.value === selected))
    const delta = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1
    const next = scope.options[(index + delta + scope.options.length) % scope.options.length]
    if (!next) return
    choose(next.value)
    event.currentTarget.querySelector<HTMLElement>(`[data-value="${next.value}"]`)?.focus()
  }
  return (
    <div role="radiogroup" aria-label={scope.label} onKeyDown={onKeyDown} className="flex gap-0.5 rounded-full bg-muted p-0.5">
      {scope.options.map((option) => {
        const checked = option.value === selected
        return (
          <button
            key={option.value}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            onClick={() => choose(option.value)}
            data-value={option.value}
            className={cn("min-w-0 flex-1 rounded-full px-2 py-1 text-xs", checked ? "bg-card text-foreground shadow-sm" : "text-muted-foreground")}
          >
            {option.label}
          </button>
        )
      })}
    </div>
  )
}

function RailSectionButton({
  item,
  pressed,
  onSelect,
}: {
  item: RailSection
  pressed: boolean
  onSelect: (id: string) => void
}) {
  const label = item.badge != null && item.badge !== "" ? `${item.label}, ${item.badge}` : item.label
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          data-rail-section=""
          aria-pressed={pressed}
          aria-label={label}
          tabIndex={pressed ? 0 : -1}
          onClick={() => onSelect(item.id)}
          className={cn(
            "relative grid size-8 place-items-center rounded-full text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            pressed && "bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground",
          )}
        >
          <span className="[&_svg]:size-4">{item.icon}</span>
          {item.badge != null && item.badge !== "" ? (
            <span className="absolute end-0.5 top-0.5 size-1.5 rounded-full bg-destructive" aria-hidden />
          ) : null}
        </button>
      </TooltipTrigger>
      <TooltipContent side="right">{label}</TooltipContent>
    </Tooltip>
  )
}

function columnProps(props: RailSidebarProps, sectionId: string, onSectionChange: (id: string) => void, panelVisible: boolean, onTogglePanel?: () => void, showCollapse = true) {
  return {
    sections: props.sections,
    sectionId,
    onSectionChange,
    activeHref: props.activeHref,
    renderLink: props.renderLink,
    onNavigate: props.onNavigate,
    workspace: props.workspace,
    user: props.user,
    footerSlot: props.footerSlot,
    onSearch: props.onSearch,
    onOpenCommand: props.onOpenCommand,
    searchPlaceholder: props.searchPlaceholder,
    type: props.type,
    mark: props.mark,
    markLabel: props.markLabel,
    railClassName: props.railClassName,
    panelClassName: props.panelClassName,
    itemClassName: props.itemClassName,
    groupClassName: props.groupClassName,
    headerClassName: props.headerClassName,
    footerClassName: props.footerClassName,
    searchClassName: props.searchClassName,
    railLabel: props.railLabel,
    panelLabel: props.panelLabel,
    searchLabel: props.searchLabel,
    commandLabel: props.commandLabel,
    collapseLabel: props.collapseLabel,
    expandLabel: props.expandLabel,
    scope: props.scope,
    footerLinks: props.footerLinks,
    panelVisible,
    onTogglePanel,
    showCollapse,
  }
}

function ContainedRail(props: RailSidebarProps) {
  const [sectionId, setSectionId] = useControllable(
    props.value,
    props.defaultValue ?? props.sections[0]?.id,
    props.onValueChange,
  )
  const [panelOpen, setPanelOpen] = React.useState(true)
  const collapsible = props.collapsible ?? "icon"
  const panelVisible = collapsible === "none" ? true : panelOpen
  return (
    <div className={cn("flex h-full min-h-0 w-full overflow-hidden rounded-xl border border-border bg-card", props.className)}>
      <RailColumns
        {...columnProps(
          props,
          sectionId,
          setSectionId,
          panelVisible,
          collapsible === "none" ? undefined : () => setPanelOpen((open) => !open),
          collapsible !== "none",
        )}
      />
    </div>
  )
}

function ShellRail(props: RailSidebarProps) {
  const { state, isMobile, toggleSidebar } = useSidebar()
  const [sectionId, setSectionId] = useControllable(
    props.value,
    props.defaultValue ?? props.sections[0]?.id,
    props.onValueChange,
  )
  const collapsible = props.collapsible ?? "icon"
  const panelVisible = collapsible === "none" ? true : isMobile || state === "expanded"
  return (
    <>
      <Sidebar
        collapsible={collapsible}
        className="border-0 bg-transparent"
        style={{ "--sidebar-width": "20rem" } as React.CSSProperties}
      >
        <div className="flex h-full min-h-0 overflow-hidden bg-sidebar md:my-2 md:ms-2 md:rounded-xl md:border md:border-border md:bg-card md:shadow-sm">
          <RailColumns
            {...columnProps(props, sectionId, setSectionId, panelVisible, toggleSidebar, collapsible !== "none")}
          />
        </div>
      </Sidebar>
      <SidebarInset className={props.insetClassName}>
        <div className="flex items-center gap-2 border-b border-border p-2 md:hidden">
          <SidebarTrigger />
        </div>
        {props.children}
      </SidebarInset>
    </>
  )
}

export function RailSidebar(props: RailSidebarProps) {
  if (props.contained) return <ContainedRail {...props} />
  return (
    <SidebarProvider
      className={cn("min-h-svh", props.className)}
      style={{ "--sidebar-width": "20rem", "--sidebar-width-icon": "3rem" } as React.CSSProperties}
    >
      <ShellRail {...props} />
    </SidebarProvider>
  )
}

export { SidebarTrigger as RailSidebarTrigger }

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { formatDashboardValue, type DashboardFormat } from "@/lib/dashboard-format"

export type TrendPoint = { x: number | string; y: number }

export type TrendSeries = {
  id: string
  label: string
  points: readonly TrendPoint[]
  emphasis?: "primary" | "muted"
}

export type TrendBand = {
  from: number | string
  to: number | string
  label: string
  tone?: "highlight" | "secondary"
}

export type TrendMarker = { x: number | string; label: string }

export type AnnotatedTrendChartClassNames = {
  root?: string
  plot?: string
  tooltip?: string
  table?: string
}

export type AnnotatedTrendChartProps = {
  series: readonly TrendSeries[]
  /** Accessible name. A summary is appended from the primary series. */
  label: string
  target?: { y: number; label: string }
  bands?: readonly TrendBand[]
  markers?: readonly TrendMarker[]
  endLabel?: boolean
  yFormat?: DashboardFormat
  locale?: string
  currency?: string
  area?: boolean
  /** When false, muted series stay hidden. */
  compare?: boolean
  height?: number
  className?: string
  classNames?: AnnotatedTrendChartClassNames
}

function keyOf(value: number | string) {
  return String(value)
}

function smoothPath(points: { x: number; y: number }[]) {
  if (!points.length) return ""
  if (points.length === 1) return `M ${points[0].x} ${points[0].y}`
  let path = `M ${points[0].x.toFixed(2)} ${points[0].y.toFixed(2)}`
  for (let index = 0; index < points.length - 1; index += 1) {
    const p0 = points[index - 1] ?? points[index]
    const p1 = points[index]
    const p2 = points[index + 1]
    const p3 = points[index + 2] ?? p2
    const c1x = p1.x + (p2.x - p0.x) / 6
    const c1y = p1.y + (p2.y - p0.y) / 6
    const c2x = p2.x - (p3.x - p1.x) / 6
    const c2y = p2.y - (p3.y - p1.y) / 6
    path += ` C ${c1x.toFixed(2)} ${c1y.toFixed(2)}, ${c2x.toFixed(2)} ${c2y.toFixed(2)}, ${p2.x.toFixed(2)} ${p2.y.toFixed(2)}`
  }
  return path
}

function buildSummary(label: string, primary: TrendSeries | undefined, format: (value: number) => string, target?: { y: number; label: string }) {
  if (!primary?.points.length) return label
  const first = primary.points[0]
  const last = primary.points[primary.points.length - 1]
  const direction = last.y === first.y ? "held" : last.y > first.y ? "rose" : "fell"
  const targetText = target ? `; ${target.label}` : ""
  return `${label}: ${primary.label} ${direction} from ${format(first.y)} to ${format(last.y)} over ${primary.points.length} points${targetText}`
}

export function AnnotatedTrendChart({
  series,
  label,
  target,
  bands = [],
  markers = [],
  endLabel = true,
  yFormat = "number",
  locale = "en-US",
  currency = "USD",
  area = true,
  compare = true,
  height = 220,
  className,
  classNames,
}: AnnotatedTrendChartProps) {
  const format = React.useCallback(
    (value: number) => formatDashboardValue(value, yFormat, locale, currency),
    [currency, locale, yFormat],
  )
  const visible = series.filter((line) => compare || line.emphasis !== "muted")
  const keys: string[] = []
  for (const line of visible) {
    for (const point of line.points) {
      const key = keyOf(point.x)
      if (!keys.includes(key)) keys.push(key)
    }
  }
  const [width, setWidth] = React.useState(640)
  const [index, setIndex] = React.useState<number | null>(null)
  const [tableOpen, setTableOpen] = React.useState(false)
  const plotRef = React.useRef<HTMLDivElement>(null)
  const gradientId = React.useId().replace(/:/g, "")

  React.useEffect(() => {
    const node = plotRef.current
    if (!node || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver((entries) => {
      const next = entries[0]?.contentRect.width
      if (next && next > 0) setWidth(next)
    })
    observer.observe(node)
    return () => observer.disconnect()
  }, [])

  const compact = width < 360
  const pad = { left: 40, right: compact || !endLabel ? 12 : 72, top: 28, bottom: 28 }
  const innerW = Math.max(1, width - pad.left - pad.right)
  const innerH = Math.max(1, height - pad.top - pad.bottom)
  const values = visible.flatMap((line) => line.points.map((point) => point.y))
  if (target) values.push(target.y)
  const min = values.length ? Math.min(...values) : 0
  const max = values.length ? Math.max(...values) : 1
  const span = max - min || 1
  const yAt = (value: number) => pad.top + innerH - ((value - min) / span) * innerH
  const xAt = (key: string) => {
    const at = Math.max(0, keys.indexOf(key))
    const step = keys.length <= 1 ? 0 : at / (keys.length - 1)
    return pad.left + step * innerW
  }
  const primary = visible.find((line) => line.emphasis !== "muted") ?? visible[0]
  const summary = buildSummary(label, primary, format, target)
  const ticks = 4
  const yTicks = Array.from({ length: ticks }, (_, step) => min + (span * step) / (ticks - 1))
  const xTickCount = compact ? 2 : Math.min(4, keys.length)
  const xTicks = Array.from({ length: xTickCount }, (_, step) => keys[Math.round((step * (keys.length - 1)) / Math.max(1, xTickCount - 1))] ?? keys[0])

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (!keys.length) return
    const last = keys.length - 1
    if (event.key === "Escape") {
      setIndex(null)
      return
    }
    if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return
    event.preventDefault()
    setIndex((current) => {
      if (current == null) {
        if (event.key === "End" || event.key === "ArrowLeft") return last
        return 0
      }
      if (event.key === "Home") return 0
      if (event.key === "End") return last
      if (event.key === "ArrowRight") return Math.min(last, current + 1)
      return Math.max(0, current - 1)
    })
  }

  const activeKey = index != null ? keys[index] : null

  return (
    <div data-slot="annotated-trend-chart" className={cn("min-w-0", className, classNames?.root)}>
      <div ref={plotRef} className={cn("relative min-w-0", classNames?.plot)}>
        <div
          role="img"
          tabIndex={0}
          aria-label={summary}
          onKeyDown={onKeyDown}
          className="outline-none focus-visible:ring-2 focus-visible:ring-ring rounded-md"
        >
          <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} className="block text-foreground" aria-hidden>
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="var(--chart-3)" stopOpacity="0.35" />
                <stop offset="1" stopColor="var(--chart-3)" stopOpacity="0" />
              </linearGradient>
            </defs>
            {yTicks.map((tick) => (
              <g key={tick}>
                <line x1={pad.left} x2={width - pad.right} y1={yAt(tick)} y2={yAt(tick)} className="stroke-border" strokeDasharray="2 4" />
                <text x={pad.left - 6} y={yAt(tick) + 3} textAnchor="end" className="fill-muted-foreground text-[10px]">
                  {format(tick)}
                </text>
              </g>
            ))}
            {bands.map((band) => {
              const x1 = xAt(keyOf(band.from))
              const x2 = xAt(keyOf(band.to))
              const left = Math.min(x1, x2)
              return (
                <g key={band.label}>
                  <rect
                    x={left}
                    y={pad.top}
                    width={Math.max(2, Math.abs(x2 - x1))}
                    height={innerH}
                    className={band.tone === "secondary" ? "fill-chart-3" : "fill-chart-2"}
                    fillOpacity={0.25}
                  />
                  <text x={left + 4} y={pad.top + 12} className="fill-foreground text-[10px]">
                    {band.label}
                  </text>
                </g>
              )
            })}
            {target ? (
              <g>
                <line
                  x1={pad.left}
                  x2={width - pad.right}
                  y1={yAt(target.y)}
                  y2={yAt(target.y)}
                  className="stroke-destructive"
                  strokeDasharray="4 4"
                />
                <text x={width - pad.right} y={Math.max(12, yAt(target.y) - 6)} textAnchor="end" className="fill-destructive text-[10px]">
                  {target.label}
                </text>
              </g>
            ) : null}
            {visible.map((line) => {
              const points = line.points.map((point) => ({ x: xAt(keyOf(point.x)), y: yAt(point.y) }))
              const d = smoothPath(points)
              const muted = line.emphasis === "muted"
              const last = points[points.length - 1]
              const areaPath = points.length
                ? `${d} L ${points[points.length - 1].x.toFixed(2)} ${(pad.top + innerH).toFixed(2)} L ${points[0].x.toFixed(2)} ${(pad.top + innerH).toFixed(2)} Z`
                : ""
              return (
                <g key={line.id}>
                  {area && !muted && areaPath ? <path d={areaPath} fill={`url(#${gradientId})`} /> : null}
                  <path
                    d={d}
                    fill="none"
                    className={muted ? "stroke-chart-3" : "stroke-primary"}
                    strokeWidth={muted ? 1.5 : 2}
                    strokeOpacity={muted ? 0.7 : 1}
                    strokeLinejoin="round"
                    strokeLinecap="round"
                  />
                  {endLabel && !compact && muted && last ? (
                    <text x={last.x + 6} y={last.y + 4} className="fill-muted-foreground text-[10px]">
                      {line.label}
                    </text>
                  ) : null}
                </g>
              )
            })}
            {primary && primary.points.length ? (
              <g>
                {(() => {
                  const last = primary.points[primary.points.length - 1]
                  const x = xAt(keyOf(last.x))
                  const y = yAt(last.y)
                  return (
                    <>
                      <circle cx={x} cy={y} r="5" className="fill-chart-2 stroke-primary" strokeWidth="2" />
                      <rect x={x - 22} y={y - 26} width="44" height="16" rx="8" className="fill-primary" />
                      <text x={x} y={y - 15} textAnchor="middle" className="fill-primary-foreground text-[10px]">
                        {format(last.y)}
                      </text>
                    </>
                  )
                })()}
              </g>
            ) : null}
            {activeKey ? (
              <line x1={xAt(activeKey)} x2={xAt(activeKey)} y1={pad.top} y2={pad.top + innerH} className="stroke-foreground" strokeDasharray="2 3" />
            ) : null}
            {xTicks.filter(Boolean).map((key) => (
              <text key={key} x={xAt(key)} y={height - 8} textAnchor="middle" className="fill-muted-foreground text-[10px]">
                {key}
              </text>
            ))}
            {markers.map((marker) => (
              <text key={marker.label} x={xAt(keyOf(marker.x))} y={pad.top - 8} textAnchor="middle" className="fill-foreground text-[10px]">
                {marker.label}
              </text>
            ))}
          </svg>
        </div>
        {activeKey ? (
          <div
            data-slot="annotated-trend-tooltip"
            className={cn("mt-2 rounded-lg bg-popover px-3 py-2 text-xs text-popover-foreground shadow-sm ring-1 ring-foreground/10", classNames?.tooltip)}
          >
            <p className="font-medium">{activeKey}</p>
            <ul>
              {visible.map((line) => {
                const point = line.points.find((item) => keyOf(item.x) === activeKey)
                if (!point) return null
                return (
                  <li key={line.id}>
                    {line.label}: {format(point.y)}
                  </li>
                )
              })}
            </ul>
          </div>
        ) : null}
      </div>
      {compact && endLabel ? (
        <ul className="mt-2 flex flex-wrap gap-3 text-xs text-muted-foreground">
          {visible.map((line) => (
            <li key={line.id} className="inline-flex items-center gap-1">
              <span className={cn("h-0.5 w-4", line.emphasis === "muted" ? "bg-chart-3" : "bg-primary")} aria-hidden />
              {line.label}
            </li>
          ))}
        </ul>
      ) : null}
      <Button type="button" variant="ghost" size="sm" className="mt-2" aria-expanded={tableOpen} onClick={() => setTableOpen((open) => !open)}>
        {tableOpen ? "Hide data" : "View data"}
      </Button>
      <table className={cn("text-left text-sm", tableOpen ? "mt-2 w-full" : "sr-only", classNames?.table)}>
        <caption className="sr-only">{summary}</caption>
        <thead>
          <tr>
            <th scope="col">Point</th>
            {visible.map((line) => (
              <th key={line.id} scope="col">
                {line.label}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {keys.map((key) => (
            <tr key={key}>
              <th scope="row">{key}</th>
              {visible.map((line) => {
                const point = line.points.find((item) => keyOf(item.x) === key)
                return <td key={line.id}>{point ? format(point.y) : "—"}</td>
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

"use client"

/** Independent implementation of a common dashboard pattern. */

import * as React from "react"
import { ChevronRight, MoreHorizontal } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"
import { PriorityBadge, type PriorityLevel } from "@/components/ui/priority-badge"

export type AttentionChip =
  | { type: "priority"; level: PriorityLevel; label?: string }
  | { type: "date"; label: string }
  | { type: "status"; label: string; tone?: "neutral" | "good" | "bad" }
  | { type: "progress"; done: number; total: number }
  | { type: "text"; label: string }

export type AttentionAction = {
  id: string
  label: string
  onSelect: () => void
}

export type AttentionItem = {
  id: string
  title: string
  description?: string
  tone?: "critical" | "neutral" | "positive"
  chips?: readonly AttentionChip[]
  href?: string
  onSelect?: (item: AttentionItem) => void
  actions?: readonly AttentionAction[]
}

export type AttentionListClassNames = {
  root?: string
  item?: string
  title?: string
  description?: string
  empty?: string
}

export type AttentionListProps = {
  items: readonly AttentionItem[]
  label?: string
  max?: number
  moreLabel?: (hidden: number) => string
  emptyLabel?: string
  emptyHint?: string
  loading?: boolean
  loadingRows?: number
  className?: string
  classNames?: AttentionListClassNames
}

const tileClass = {
  critical: "bg-destructive/10 text-destructive",
  neutral: "bg-muted text-muted-foreground",
  positive: "bg-chart-2/20 text-foreground",
} as const

function chipText(chip: AttentionChip): string {
  if (chip.type === "priority") return chip.label ?? chip.level
  if (chip.type === "progress") return `${chip.done} of ${chip.total}`
  return chip.label
}

function rowName(item: AttentionItem): string {
  const chips = (item.chips ?? []).map(chipText).filter(Boolean)
  return [item.title, ...chips].join(", ")
}

function Chips({ chips }: { chips: readonly AttentionChip[] }) {
  return (
    <div className="flex flex-wrap gap-1" aria-hidden>
      {chips.map((chip, index) => {
        if (chip.type === "priority") return <PriorityBadge key={`${chip.level}-${index}`} level={chip.level} label={chip.label} />
        const tone = chip.type === "status" ? chip.tone : undefined
        return (
          <span
            key={`${chip.type}-${index}`}
            className={cn(
              "inline-flex h-6 max-w-full items-center rounded-full bg-muted px-2 text-xs text-foreground",
              tone === "good" && "bg-chart-2/20",
              tone === "bad" && "bg-destructive/10 text-destructive",
              chip.type === "progress" && "bg-chart-2/15",
            )}
          >
            <span className="truncate">{chipText(chip)}</span>
          </span>
        )
      })}
    </div>
  )
}

export function AttentionList({
  items,
  label = "Needs you",
  max,
  moreLabel = (hidden) => `Show ${hidden} more`,
  emptyLabel = "You're all caught up",
  emptyHint = "Nothing is waiting on you.",
  loading = false,
  loadingRows = 3,
  className,
  classNames,
}: AttentionListProps) {
  const [open, setOpen] = React.useState(false)
  const visible = max != null && !open ? items.slice(0, max) : items
  const hidden = items.length - visible.length

  function onRowKey(event: React.KeyboardEvent<HTMLElement>, index: number) {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp") return
    const rows = event.currentTarget.closest("ul")?.querySelectorAll<HTMLElement>("[data-attention-row]")
    if (!rows?.length) return
    event.preventDefault()
    const next = event.key === "ArrowDown" ? Math.min(rows.length - 1, index + 1) : Math.max(0, index - 1)
    rows[next]?.focus()
  }

  return (
    <div data-slot="attention-list" className={cn("min-w-0", className, classNames?.root)}>
      {loading ? (
        <ul className="flex flex-col gap-3" aria-busy="true" aria-label={label}>
          {Array.from({ length: loadingRows }, (_, index) => (
            <li key={index} className="flex gap-3">
              <Skeleton className="size-8 shrink-0" />
              <div className="flex flex-1 flex-col gap-2">
                <Skeleton className="h-4 w-2/3" />
                <Skeleton className="h-3 w-full" />
              </div>
            </li>
          ))}
        </ul>
      ) : items.length === 0 ? (
        <div className={cn("flex flex-col items-start gap-1 py-4", classNames?.empty)}>
          <p className="text-sm font-medium">{emptyLabel}</p>
          <p className="text-xs text-muted-foreground">{emptyHint}</p>
        </div>
      ) : (
        <ul role="list" aria-label={label} className="flex flex-col">
          {visible.map((item, index) => {
            const tone = item.tone ?? "neutral"
            const name = rowName(item)
            const interactive = Boolean(item.href || item.onSelect)
            const body = (
              <>
                <span className={cn("grid size-8 shrink-0 place-items-center rounded-lg text-xs font-medium", tileClass[tone])} aria-hidden>
                  {index + 1}
                </span>
                <span className="min-w-0 flex-1">
                  <span className={cn("block truncate text-sm font-medium", classNames?.title)}>{item.title}</span>
                  {item.description ? (
                    <span className={cn("mt-0.5 line-clamp-2 block text-xs text-muted-foreground", classNames?.description)}>
                      {item.description}
                    </span>
                  ) : null}
                  {item.chips?.length ? (
                    <span className="mt-2 block">
                      <Chips chips={item.chips} />
                    </span>
                  ) : null}
                </span>
                {interactive ? <ChevronRight className="size-4 shrink-0 text-muted-foreground" aria-hidden /> : null}
              </>
            )
            const rowClass = cn(
              "flex w-full min-w-0 items-start gap-3 rounded-lg py-3 text-start hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              index > 0 && "border-t border-border",
              classNames?.item,
            )
            return (
              <li key={item.id} className="flex min-w-0 items-start gap-1">
                {item.href ? (
                  <a
                    data-attention-row=""
                    href={item.href}
                    aria-label={name}
                    className={cn(rowClass, "flex-1")}
                    onClick={(event) => {
                      if (!item.onSelect) return
                      event.preventDefault()
                      item.onSelect(item)
                    }}
                    onKeyDown={(event) => onRowKey(event, index)}
                  >
                    {body}
                  </a>
                ) : interactive ? (
                  <button
                    data-attention-row=""
                    type="button"
                    aria-label={name}
                    className={cn(rowClass, "flex-1")}
                    onClick={() => item.onSelect?.(item)}
                    onKeyDown={(event) => onRowKey(event, index)}
                  >
                    {body}
                  </button>
                ) : (
                  <div className={cn(rowClass, "flex-1")}>{body}</div>
                )}
                {item.actions?.length ? (
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button type="button" variant="ghost" size="icon-sm" className="mt-2 shrink-0" aria-label={`Actions for ${item.title}`}>
                        <MoreHorizontal />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end">
                      {item.actions.map((action) => (
                        <DropdownMenuItem key={action.id} onSelect={() => action.onSelect()}>
                          {action.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                ) : null}
              </li>
            )
          })}
        </ul>
      )}
      {hidden > 0 ? (
        <Button type="button" variant="ghost" size="sm" className="mt-1" onClick={() => setOpen(true)}>
          {moreLabel(hidden)}
        </Button>
      ) : null}
    </div>
  )
}

